import re
import hmac
import hashlib
import secrets
from typing import Optional, Dict, List
from dataclasses import dataclass, field
from email.headerregistry import Address
from email.message import EmailMessage
import smtplib


@dataclass
class TenantConfig:
    tenant_id: str
    domain: str
    smtp_host: str
    smtp_port: int = 587
    api_key_hash: bytes = field(default_factory=bytes)
    allowed_sender_patterns: List[str] = field(default_factory=list)
    max_recipients: int = 50
    custom_headers: Dict[str, str] = field(default_factory=dict)


class TenantRegistry:
    def __init__(self):
        self._tenants: Dict[str, TenantConfig] = {}

    def register(self, config: TenantConfig, api_key: str):
        config.api_key_hash = hashlib.pbkdf2_hmac(
            'sha256', api_key.encode(), config.tenant_id.encode(), 100000
        )
        self._tenants[config.tenant_id] = config

    def get(self, tenant_id: str) -> Optional[TenantConfig]:
        return self._tenants.get(tenant_id)

    def authenticate(self, tenant_id: str, api_key: str) -> bool:
        config = self._tenants.get(tenant_id)
        if not config:
            return False
        candidate = hashlib.pbkdf2_hmac(
            'sha256', api_key.encode(), tenant_id.encode(), 100000
        )
        return hmac.compare_digest(candidate, config.api_key_hash)


class HeaderSanitizer:
    """Sanitizes email headers to prevent injection attacks."""

    # Pattern to detect CRLF injection attempts
    _INJECTION_PATTERN = re.compile(r'[\r\n]')
    # Pattern for valid email display names
    _DISPLAY_NAME_PATTERN = re.compile(r'^[\w\s.\-,\'"()]+$')

    @classmethod
    def sanitize_header_value(cls, value: str) -> str:
        """Remove any CR/LF characters from header values."""
        if cls._INJECTION_PATTERN.search(value):
            raise ValueError(f"Header injection attempt detected in value: {repr(value[:50])}")
        return value.strip()

    @classmethod
    def validate_email_address(cls, addr: str) -> str:
        """Validate and normalize an email address."""
        addr = addr.strip()
        if cls._INJECTION_PATTERN.search(addr):
            raise ValueError("Invalid characters in email address")
        # Basic structural validation
        if '@' not in addr or addr.count('@') != 1:
            raise ValueError(f"Invalid email address format: {addr}")
        local, domain = addr.rsplit('@', 1)
        if not local or not domain or '.' not in domain:
            raise ValueError(f"Invalid email address: {addr}")
        return addr

    @classmethod
    def sanitize_display_name(cls, name: str) -> str:
        """Sanitize display name component."""
        if cls._INJECTION_PATTERN.search(name):
            raise ValueError("Invalid characters in display name")
        return name.strip()


class EmailComposer:
    """Composes emails with proper header handling."""

    def __init__(self, tenant_config: TenantConfig):
        self._config = tenant_config
        self._sanitizer = HeaderSanitizer()

    def _resolve_sender_address(self, sender_input: str) -> str:
        """Resolve and validate sender address against tenant policy."""
        # Parse potential "Display Name <email>" format
        match = re.match(r'^(.+?)\s*<(.+?)>\s*$', sender_input)
        if match:
            display_name = match.group(1)
            email_addr = match.group(2)
            display_name = self._sanitizer.sanitize_display_name(display_name)
            email_addr = self._sanitizer.validate_email_address(email_addr)
            return f"{display_name} <{email_addr}>"
        else:
            return self._sanitizer.validate_email_address(sender_input)

    def _check_sender_policy(self, sender_email: str) -> bool:
        """Check if sender is allowed by tenant policy."""
        for pattern in self._config.allowed_sender_patterns:
            if re.match(pattern, sender_email):
                return True
        # Default: sender must be from tenant domain
        return sender_email.endswith(f"@{self._config.domain}")

    def _apply_tenant_headers(self, msg: EmailMessage) -> None:
        """Apply tenant-specific custom headers."""
        for key, value in self._config.custom_headers.items():
            sanitized_key = self._sanitizer.sanitize_header_value(key)
            sanitized_value = self._sanitizer.sanitize_header_value(value)
            msg[f"X-Tenant-{sanitized_key}"] = sanitized_value

    def compose(self, sender: str, recipients: List[str], subject: str,
                body: str, reply_to: Optional[str] = None,
                extra_headers: Optional[Dict[str, str]] = None) -> EmailMessage:
        """Compose a complete email message."""
        if len(recipients) > self._config.max_recipients:
            raise ValueError(f"Too many recipients (max {self._config.max_recipients})")

        msg = EmailMessage()

        # Set sender
        resolved_sender = self._resolve_sender_address(sender)
        msg['From'] = resolved_sender

        # Validate and set recipients
        validated_recipients = []
        for r in recipients:
            validated_recipients.append(self._sanitizer.validate_email_address(r))
        msg['To'] = ', '.join(validated_recipients)

        # Set subject
        msg['Subject'] = self._sanitizer.sanitize_header_value(subject)

        # Set reply-to if provided
        if reply_to:
            msg['Reply-To'] = self._sanitizer.validate_email_address(reply_to)

        # Apply extra headers with sanitization
        if extra_headers:
            for key, value in extra_headers.items():
                safe_key = self._sanitizer.sanitize_header_value(key)
                safe_value = self._sanitizer.sanitize_header_value(value)
                msg[safe_key] = safe_value

        # Apply tenant custom headers
        self._apply_tenant_headers(msg)

        # Set body
        msg.set_content(body)

        # Add isolation headers
        msg['X-Tenant-ID'] = self._config.tenant_id
        msg['X-Mailer'] = 'CloudSDK/2.1.0'

        return msg


class NotificationService:
    """Multi-tenant notification service with email delivery."""

    def __init__(self, registry: TenantRegistry):
        self._registry = registry
        self._rate_limits: Dict[str, int] = {}

    def send_notification(self, tenant_id: str, api_key: str,
                          notification_type: str, recipient: str,
                          context: Dict[str, str]) -> bool:
        """Send a templated notification email."""
        if not self._registry.authenticate(tenant_id, api_key):
            raise PermissionError("Authentication failed")

        config = self._registry.get(tenant_id)
        composer = EmailComposer(config)

        # Build notification from template
        subject = self._render_template(
            f"notifications/{notification_type}/subject.txt", context
        )
        body = self._render_template(
            f"notifications/{notification_type}/body.txt", context
        )

        sender = f"notifications@{config.domain}"

        # The context may include a 'reply_to' override from user input
        reply_to = context.get('reply_to')

        # Build extra headers from context - this is where tenant customization happens
        extra_headers = {}
        for key, value in context.items():
            if key.startswith('header_'):
                header_name = key[7:]  # Strip 'header_' prefix
                extra_headers[header_name] = value

        msg = composer.compose(
            sender=sender,
            recipients=[recipient],
            subject=subject,
            body=body,
            reply_to=reply_to,
            extra_headers=extra_headers
        )

        return self._deliver(msg, config)

    def send_custom_email(self, tenant_id: str, api_key: str,
                          sender_name: str, sender_addr: str,
                          recipients: List[str], subject: str,
                          body: str, headers: Optional[Dict[str, str]] = None) -> bool:
        """Send a custom email on behalf of a tenant."""
        if not self._registry.authenticate(tenant_id, api_key):
            raise PermissionError("Authentication failed")

        config = self._registry.get(tenant_id)
        composer = EmailComposer(config)

        # Construct sender with display name
        full_sender = f"{sender_name} <{sender_addr}>"

        msg = composer.compose(
            sender=full_sender,
            recipients=recipients,
            subject=subject,
            body=body,
            extra_headers=headers
        )

        return self._deliver(msg, config)

    def _render_template(self, template_path: str, context: Dict[str, str]) -> str:
        """Simple template rendering (placeholder for real template engine)."""
        # In production this would use Jinja2 with autoescape
        template = f"Notification: {context.get('message', '')}"
        return template

    def _deliver(self, msg: EmailMessage, config: TenantConfig) -> bool:
        """Deliver email via tenant's SMTP configuration."""
        try:
            with smtplib.SMTP(config.smtp_host, config.smtp_port) as server:
                server.starttls()
                server.send_message(msg)
            return True
        except Exception:
            return False


# SDK public interface
class CloudEmailSDK:
    """Public SDK interface for multi-tenant email operations."""

    def __init__(self):
        self._registry = TenantRegistry()
        self._service = NotificationService(self._registry)

    def register_tenant(self, tenant_id: str, domain: str,
                        smtp_host: str, api_key: str,
                        allowed_senders: Optional[List[str]] = None,
                        custom_headers: Optional[Dict[str, str]] = None) -> str:
        """Register a new tenant. Returns the API key."""
        config = TenantConfig(
            tenant_id=tenant_id,
            domain=domain,
            smtp_host=smtp_host,
            allowed_sender_patterns=allowed_senders or [],
            custom_headers=custom_headers or {}
        )
        self._registry.register(config, api_key)
        return api_key

    def send_notification(self, tenant_id: str, api_key: str,
                          notification_type: str, recipient: str,
                          context: Dict[str, str]) -> bool:
        return self._service.send_notification(
            tenant_id, api_key, notification_type, recipient, context
        )

    def send_email(self, tenant_id: str, api_key: str,
                   sender_name: str, sender_addr: str,
                   recipients: List[str], subject: str,
                   body: str, headers: Optional[Dict[str, str]] = None) -> bool:
        return self._service.send_custom_email(
            tenant_id, api_key, sender_name, sender_addr,
            recipients, subject, body, headers
        )
